  41|
  42|// RunGit executes a git command in the given directory and returns stdout.
  43|// Returns GitError on non-zero exit, with both stderr and stdout captured.
  44|func RunGit(args []string, cwd string) (string, error) {
  45|	cmd := exec.Command("git", args...)
  46|	if cwd != "" {
  47|		cmd.Dir = cwd
  48|	}
  49|
  50|	stdout, err := cmd.Output()
  51|	if err != nil {
  52|		exitErr, ok := err.(*exec.ExitError)
  53|		if ok {
  54|			return "", &GitError{
  55|				Command:    fmt.Sprintf("git %s", strings.Join(args, " ")),
  56|				ReturnCode: exitErr.ExitCode(),
  57|				Stderr:     strings.TrimSpace(string(exitErr.Stderr)),
  58|				Stdout:     strings.TrimSpace(string(stdout)),
  59|			}
  60|		}
  61|		return "", fmt.Errorf("failed to run git %s: %w", strings.Join(args, " "), err)
  62|	}
  63|
  64|	return strings.TrimSpace(string(stdout)), nil
  65|}
