  67|// GetCommitLog returns commits since baseRef (up to maxCount).
  68|// Uses: git log --format="%H|%h|%an|%aI|%s" <baseRef>..HEAD
  69|func GetCommitLog(worktreePath, baseRef string, maxCount int) ([]CommitInfo, error) {
  70|	sep := "---COMMIT-SEP---"
  71|	format := fmt.Sprintf("%%H%s%%h%s%%an%s%%aI%s%%s", sep, sep, sep, sep)
  72|
  73|	output, err := RunGit([]string{
  74|		"log",
  75|		fmt.Sprintf("--format=%s", format),
  76|		fmt.Sprintf("--max-count=%d", maxCount),
  77|		fmt.Sprintf("%s..HEAD", baseRef),
  78|	}, worktreePath)
  79|	if err != nil {
  80|		return nil, fmt.Errorf("get commit log: %w", err)
  81|	}
  82|
  83|	if output == "" {
  84|		return nil, nil
  85|	}
  86|
  87|	var commits []CommitInfo
  88|	for _, line := range strings.Split(output, "\n") {
  89|		parts := strings.SplitN(line, sep, 5)
  90|		if len(parts) != 5 {
  91|			continue
  92|		}
  93|
  94|		date, parseErr := time.Parse(time.RFC3339, parts[3])
  95|		if parseErr != nil {
  96|			// Fall back to zero time if parsing fails
  97|			date = time.Time{}
  98|		}
  99|
 100|		commits = append(commits, CommitInfo{
 101|			SHA:      parts[0],
 102|			ShortSHA: parts[1],
 103|			Author:   parts[2],
 104|			Date:     date,
 105|			Message:  parts[4],
 106|		})
 107|	}
 108|
 109|	return commits, nil
 110|}
