 129|// IsClean returns true if the worktree has no uncommitted changes.
 130|// Uses: git status --porcelain
 131|// Ignores .claude/ directory entries in the output.
 132|func IsClean(worktreePath string) (bool, error) {
 133|	output, err := RunGit([]string{"status", "--porcelain"}, worktreePath)
 134|	if err != nil {
 135|		return false, fmt.Errorf("check clean status: %w", err)
 136|	}
 137|
 138|	if output == "" {
 139|		return true, nil
 140|	}
 141|
 142|	// Filter out .claude/ directory entries
 143|	for _, line := range strings.Split(output, "\n") {
 144|		// Each porcelain line has a 2-char status prefix followed by a space and path
 145|		trimmed := strings.TrimSpace(line)
 146|		if trimmed == "" {
 147|			continue
 148|		}
 149|		// Extract the file path (skip the 2-char status + space)
 150|		if len(line) > 3 {
 151|			path := line[3:]
 152|			if strings.HasPrefix(path, ".claude/") {
 153|				continue
 154|			}
 155|		}
 156|		// Found a non-.claude/ dirty file
 157|		return false, nil
 158|	}
 159|
 160|	return true, nil
 161|}
