 163|// CommitUnstagedChanges stages all non-.claude/ changes and commits them.
 164|// Returns true if a commit was created, false if there was nothing to commit.
 165|func CommitUnstagedChanges(worktreePath, message string) (bool, error) {
 166|	clean, err := IsClean(worktreePath)
 167|	if err != nil {
 168|		return false, fmt.Errorf("commit unstaged: check clean: %w", err)
 169|	}
 170|	if clean {
 171|		return false, nil
 172|	}
 173|
 174|	// Stage only tracked (modified/deleted) files. Using -u instead of --all
 175|	// avoids staging untracked files such as build artifacts, editor configs,
 176|	// and other files not yet in the index, which would cause merge conflicts
 177|	// when multiple agents commit overlapping untracked files.
 178|	if _, err := RunGit([]string{"add", "-u", "--", "."}, worktreePath); err != nil {
 179|		return false, fmt.Errorf("commit unstaged: add: %w", err)
 180|	}
 181|
 182|	// Unstage any .claude/ files that were tracked and staged above.
 183|	// This prevents worktree-specific .claude/settings.json from being committed.
 184|	// Errors are ignored — reset fails if no .claude/ files are staged, which is fine.
 185|	_, _ = RunGit([]string{"reset", "HEAD", "--", ".claude/"}, worktreePath)
 186|
 187|	// Check if anything was actually staged (-u may have nothing if there are no tracked changes).
 188|	if _, err := RunGit([]string{"diff", "--cached", "--quiet"}, worktreePath); err == nil {
 189|		// Exit code 0 means no staged differences — nothing to commit.
 190|		return false, nil
 191|	}
 192|
 193|	if _, err := RunGit([]string{"commit", "-m", message}, worktreePath); err != nil {
 194|		return false, fmt.Errorf("commit unstaged: commit: %w", err)
 195|	}
 196|
 197|	return true, nil
 198|}
